package sg.nus.carelink.platform;

import static org.assertj.core.api.Assertions.*;

import java.nio.file.*;
import java.util.*;
import java.util.function.Supplier;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import sg.nus.carelink.testsupport.SharedMySql;

/** Disposable histories are generated by Flyway, never by editing history rows. */
class MainMigrationLineageIT {
    @TempDir Path temporary;

    @Test void freshFourServiceSchemasValidateAndSecondMigrateIsEmpty() {
        for (String service : List.of("core", "visit", "report", "notification")) {
            Database db = database();
            Flyway f = migration(db, directory(service), null);
            assertThat(f.migrate().migrationsExecuted).isPositive();
            f.validate();
            assertThat(f.migrate().migrationsExecuted).isZero();
            if (service.equals("core")) {
                assertThat(db.jdbc.queryForObject("select script from flyway_schema_history where version='26'", String.class))
                        .isEqualTo("V26__caregiver_credential_submission.sql");
                assertThat(db.jdbc.queryForObject("select script from flyway_schema_history where version='27'", String.class))
                        .isEqualTo("V27__caregiver_admission.sql");
            }
        }
    }

    @Test void coreV25UpgradePreservesLegacyIdentityAndMainV26PrefixIsLegal() {
        for (String prefix : List.of("25", "26", "28")) {
            Database db = database();
            migration(db, directory("core"), prefix).migrate();
            db.jdbc.update("insert into app_user(id,username,password_hash,display_name) values (8001,'legacy-test','{noop}unchanged','Legacy synthetic')");
            db.jdbc.update("insert into user_role(user_id,role) values (8001,'CAREGIVER')");
            db.jdbc.update("insert into caregiver(id,user_id,full_name,status) values (8002,8001,'Legacy synthetic','AVAILABLE')");
            db.jdbc.update("insert into credential_type(id,name) values (8003,'Synthetic legacy qualification')");
            db.jdbc.update("insert into credential(id,caregiver_id,credential_type_id,status,certificate_no) values (8004,8002,8003,'PUBLISHED','SYNTHETIC-LEGACY')");
            db.jdbc.update("insert into elder(id,full_name) values (8005,'Synthetic legacy elder')");
            db.jdbc.update("insert into care_plan(id,elder_id,status,version) values (8006,8005,'DRAFT',3)");
            Map<String,Object> before = db.jdbc.queryForMap("select * from app_user where id=8001");
            Map<String,Object> credential = db.jdbc.queryForMap("select * from credential where id=8004");
            Map<String,Object> plan = db.jdbc.queryForMap("select * from care_plan where id=8006");
            List<Map<String,Object>> history = db.jdbc.queryForList("select installed_rank,version,script,checksum from flyway_schema_history order by installed_rank");
            Flyway f = migration(db, directory("core"), null);
            f.migrate(); f.validate();
            assertThat(db.jdbc.queryForMap("select * from app_user where id=8001")).isEqualTo(before);
            assertThat(db.jdbc.queryForMap("select * from credential where id=8004")).isEqualTo(credential);
            assertThat(db.jdbc.queryForMap("select * from care_plan where id=8006")).isEqualTo(plan);
            assertThat(db.jdbc.queryForObject("select status from caregiver where id=8002",String.class)).isEqualTo("AVAILABLE");
            assertThat(db.jdbc.queryForObject("select role from user_role where user_id=8001",String.class)).isEqualTo("CAREGIVER");
            assertThat(db.jdbc.queryForList("select installed_rank,version,script,checksum from flyway_schema_history order by installed_rank"))
                    .containsAll(history);
            assertThat(f.migrate().migrationsExecuted).isZero();
        }
    }

    @Test void oldCoreNumberingMustBeRejectedRatherThanRepaired() throws Exception {
        Path old = temporary.resolve("old-core"); Files.createDirectory(old);
        try (var files = Files.list(directory("core"))) {
            for (Path p : files.toList()) {
                String name=p.getFileName().toString();
                if(name.equals("V26__caregiver_credential_submission.sql")) name="V27__caregiver_credential_submission.sql";
                else if(name.equals("V27__caregiver_admission.sql")) name="V26__caregiver_admission.sql";
                Files.copy(p,old.resolve(name));
            }
        }
        for (String target : List.of("26", "28")) {
            Database db=database(); migration(db,old,target).migrate();
            List<Map<String,Object>> before=db.jdbc.queryForList("select * from flyway_schema_history order by installed_rank");
            assertThat(migration(db,directory("core"),null).validateWithResult().validationSuccessful).isFalse();
            assertThatThrownBy(()->migration(db,directory("core"),null).migrate()).isInstanceOf(org.flywaydb.core.api.FlywayException.class);
            assertThat(db.jdbc.queryForList("select * from flyway_schema_history order by installed_rank")).isEqualTo(before);
        }
    }

    @Test void oldReportEvidenceV4MustNotBeAcceptedAsTaskDispatchV4() throws Exception {
        Path old=temporary.resolve("old-report"); Files.createDirectory(old);
        try(var files=Files.list(directory("report"))) {
            for(Path p:files.toList()) {
                String name=p.getFileName().toString();
                if(name.startsWith("V4__")) continue;
                if(name.equals("V5__visit_evidence_projection.sql")) name="V4__visit_evidence_projection.sql";
                Files.copy(p,old.resolve(name));
            }
        }
        Database db=database(); migration(db,old,null).migrate();
        List<Map<String,Object>> before=db.jdbc.queryForList("select * from flyway_schema_history order by installed_rank");
        assertThat(migration(db,directory("report"),null).validateWithResult().validationSuccessful).isFalse();
        assertThatThrownBy(()->migration(db,directory("report"),null).migrate()).isInstanceOf(org.flywaydb.core.api.FlywayException.class);
        assertThat(db.jdbc.queryForList("select * from flyway_schema_history order by installed_rank")).isEqualTo(before);
    }

    static Path directory(String service) { return Path.of("..",service,"src/main/resources/db/migration").toAbsolutePath(); }
    static Flyway migration(Database db,Path location,String target) {
        var config=Flyway.configure().dataSource(db.source).locations("filesystem:"+location).cleanDisabled(true);
        if(target!=null) config.target(target);
        return config.load();
    }
    static Database database() {
        Map<String,Supplier<Object>> properties=new HashMap<>();
        SharedMySql.register(properties::put,MainMigrationLineageIT.class,"+08:00","connectionTimeZone=Asia/Singapore");
        var source=new DriverManagerDataSource((String)properties.get("spring.datasource.url").get(),
                (String)properties.get("spring.datasource.username").get(),(String)properties.get("spring.datasource.password").get());
        return new Database(source,new JdbcTemplate(source));
    }
    record Database(DriverManagerDataSource source,JdbcTemplate jdbc) {}
}
